class AmosMixer extends AudioWorkletProcessor {
  constructor() {
    super()
    this.blocks = []
    this.at = 0
    this.depth = 0
    this.since = 0
    this.starved = 0
    this.port.onmessage = (e) => {
      const m = e.data
      if (m.pcm) {
        this.blocks.push(m.pcm)
        this.depth += m.pcm.length >> 1
      }
      if (typeof m.trim === 'number') {
        while (this.depth > m.trim && this.blocks.length > 1) {
          const head = this.blocks.shift()
          this.depth -= (head.length - this.at) >> 1
          this.at = 0
        }
      }
      if (m.gain !== undefined) this.gain = m.gain
    }
    this.gain = 0.4
  }

  process(inputs, outputs) {
    const out = outputs[0]
    const left = out[0]
    const right = out[1] || out[0]
    const n = left.length
    for (let i = 0; i < n; i++) {
      const head = this.blocks[0]
      if (head === undefined) {
        left[i] = 0
        right[i] = 0
        this.starved++
        continue
      }
      left[i] = head[this.at] * this.gain
      right[i] = head[this.at + 1] * this.gain
      this.at += 2
      this.depth--
      if (this.at >= head.length) {
        this.blocks.shift()
        this.at = 0
      }
    }
    this.since += n
    // about every 50ms, so the estimate on the other side stays honest
    if (this.since >= 2048) {
      this.since = 0
      this.port.postMessage({ depth: this.depth, starved: this.starved })
    }
    return true
  }
}
